let html = '';
const j = $input.first().json;
if (typeof j.data === 'string') html = j.data;
else if (typeof j.body === 'string') html = j.body;
else if (typeof j === 'string') html = j;
else if (j.data && typeof j.data === 'object') html = JSON.stringify(j.data);
else html = JSON.stringify(j);

// Se veio como objeto com chave 'data' que já é HTML, tá ok. Se não, tenta pegar raw
if (!html.includes('<html') && !html.includes('__NEXT_DATA__')) {
  // tentar outras chaves
  const v = Object.values(j).find(v => typeof v === 'string' && v.length > 5000);
  if (v) html = v;
}

const leads = [];

// 1) Tentar extrair via __NEXT_DATA__ (Next.js da OLX)
try {
  const m = html.match(/<script id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/);
  if (m) {
    const data = JSON.parse(m[1]);
    // OLX varia: props.pageProps.ads ou .searchResults ou .initialData
    const str = JSON.stringify(data);
    // Regex para achar blocos de anúncio dentro do JSON
    const titleRegex = /"title"\s*:\s*"([^"]+)"/g;
    const urlRegex = /"url"\s*:\s*"([^"]+\/d\/[^"]+)"/g;
    const priceRegex = /"price"\s*:\s*"?([\d\.]+)"?/g;
    // Heurística: tenta achar objetos com title+price juntos
    const adBlocks = [...str.matchAll(/\{[^\{\}]*"title"[^\}]*\}/g)];
    for (const b of adBlocks.slice(0, 20)) {
      try {
        const obj = JSON.parse(b[0]);
        if (obj.title && obj.title.length > 5) {
          leads.push({ nome: obj.title.slice(0, 80), preco: obj.price || '', link: obj.url || '', fonte: 'olx' });
        }
      } catch {}
    }
  }
} catch(e) {}

// 2) Fallback: regex em HTML puro - links de anúncio OLX
if (leads.length === 0) {
  const linkRegex = /<a[^>]+href="([^"]*\/d\/[^"]*)"[^>]*>([\s\S]*?)<\/a>/gi;
  let match;
  let count = 0;
  while ((match = linkRegex.exec(html)) !== null && count < 20) {
    const href = match[1];
    const inner = match[2];
    // Extrair título do inner
    const t = inner.match(/<h2[^>]*>([^<]+)<\/h2>/i) || inner.match(/title="([^"]+)"/i);
    const title = t ? t[1].trim() : (inner.replace(/<[^>]+>/g,'').trim().slice(0,60));
    const priceM = inner.match(/R\$\s*[\d\.\,]+/) || html.slice(match.index, match.index+500).match(/R\$\s*[\d\.\,]+/);
    if (title && title.length > 5) {
      const fullUrl = href.startsWith('http') ? href : 'https://www.olx.com.br' + href;
      leads.push({ nome: title.slice(0,80), preco: priceM ? priceM[0] : '', link: fullUrl, fonte: 'olx' });
      count++;
    }
  }
}

// Deduplicar por nome
const seen = new Set();
const uniq = leads.filter(l => { if (seen.has(l.nome)) return false; seen.add(l.nome); return true; });

if (uniq.length === 0) {
  return [{ json: { warning: 'Nenhum anúncio extraído', html_preview: html.slice(0, 500) } }];
}

return uniq.map(l => ({ json: l }));
